#!/usr/bin/env node

/**
 * @module scripts/generate-doc-inventory
 * @description Generates docs/_inventory.generated.md from the canonical
 *              PRODUCT_INVENTORY in src/shared/product-inventory.ts.
 *
 * Called by `npm run build` (after tsc, before generate-build-info).
 * The generated file is committed — CI verifies it stays current via
 * `npm run check:doc-drift`.
 *
 * Usage:
 *   node scripts/generate-doc-inventory.mjs
 */

import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');

async function main() {
  const { PRODUCT_INVENTORY } = await import(
    join(ROOT, 'dist', 'shared', 'product-inventory.js')
  );

  const header = `<!-- GENERATED by scripts/generate-doc-inventory.mjs — DO NOT EDIT -->
# Product Inventory (generated)

Canonical product counts derived from
[\`src/shared/product-inventory.ts\`](../src/shared/product-inventory.ts).
Verified by \`npm run check:doc-drift\`.

`;

  const rows = [
    ['Entity', 'Count', 'Code Authority'],
    ['---', '---', '---'],
    ['Machine Commands', PRODUCT_INVENTORY.machineCommands, '`src/machine/commands.ts`'],
    ['Integration Tools', PRODUCT_INVENTORY.integrationTools, '`src/integration/tools/index.ts`'],
    ['MCP Tools', PRODUCT_INVENTORY.mcpTools, '`src/mcp-server/server.ts`'],
    [
      'Installed Command Definitions',
      PRODUCT_INVENTORY.installedCommandDefs,
      '`src/integration/installed-commands.ts`',
    ],
    ['Phases', PRODUCT_INVENTORY.phases, '`src/state/schema.ts`'],
    ['Policy Modes', PRODUCT_INVENTORY.policyModes, '`src/state/policy-mode.ts`'],
    ['Profiles', PRODUCT_INVENTORY.profiles, '`src/config/profile.ts`'],
    ['Discovery Collectors', PRODUCT_INVENTORY.discoveryCollectors, '`src/discovery/orchestrator.ts`'],
    ['Review Loops', PRODUCT_INVENTORY.reviewLoops, '`src/integration/review/review-loop-progress.ts`'],
    [
      'Enforcement Layers',
      PRODUCT_INVENTORY.enforcementLayers,
      '`src/integration/review/enforcement/enforcement.ts`',
    ],
    ['Audit Event Kinds', PRODUCT_INVENTORY.auditEventKinds, '`src/audit/types.ts`'],
    ['Archive Finding Codes', PRODUCT_INVENTORY.archiveFindingCodes, '`src/archive/types.ts`'],
    [
      'Archive Verify Checks (JSDoc)',
      PRODUCT_INVENTORY.archiveVerifyJsdocChecks,
      '`src/adapters/workspace/archive-verify-chain.ts`',
    ],
    ['CLI Bins', PRODUCT_INVENTORY.cliBins, '`package.json` `bin`'],
    ['Mutation Files', PRODUCT_INVENTORY.mutationFiles, '`stryker.conf.json` `mutate`'],
  ];

  const table = rows.map((r) => `| ${r.join(' | ')} |`).join('\n');

  const footer = `
---
*Generated at build time. Committed to the repository for offline readability.*
*CI verifies this file matches the live code via \`npm run check:doc-drift\`.*
`;

  const output = header + table + '\n' + footer;
  const target = join(ROOT, 'docs', '_inventory.generated.md');
  writeFileSync(target, output, 'utf-8');
  console.log(`docs/_inventory.generated.md written (${output.length} bytes)`);

  // Format the generated file so it matches Prettier conventions.
  try {
    const { execSync } = await import('node:child_process');
    execSync('npx prettier --write docs/_inventory.generated.md', {
      cwd: ROOT,
      stdio: 'pipe',
    });
  } catch {
    // Prettier may not be available in all environments; non-fatal.
    console.warn('(prettier not available for generated file — format check may flag it)');
  }
}

main().catch((err) => {
  console.error('generate-doc-inventory failed:', err.message);
  process.exit(1);
});
